def _es_de_la_torre(descripcion):
    """Gastos que el cliente agrupa en 'Servicios generales de la torre': limpieza
    (materiales y servicio), luz del área común, gastos administrativos y
    ascensores. La luz de las bombas y lo demás va a 'comunes del condominio'."""
    d = descripcion.upper()
    return ('LIMPIEZA' in d or 'ADMINISTRATIV' in d or 'ASCENSOR' in d
            or (('ENERG' in d or 'ENEL' in d) and 'BOMBA' not in d))


def asignar_tipo_servicio(apps, schema_editor):
    """Una sola vez: pone en TORRE los gastos actuales de la torre (el resto queda
    en CONDOMINIO, el valor por defecto). Después se edita en los formularios."""
    for modelo in ('GastoFijo', 'GastoEdificio'):
        Modelo = apps.get_model('departamentos', modelo)
        ids = [g.pk for g in Modelo.objects.only('descripcion') if _es_de_la_torre(g.descripcion)]
        Modelo.objects.filter(pk__in=ids).update(tipo_servicio='TORRE')


